import { VocabCard, Language, Tag } from './types';
import { v4 as uuidv4 } from 'uuid';

function card(language: Language, targetWord: string, nativeWord: string, tags: Tag[], example?: string, exampleTranslation?: string, notes?: string): VocabCard {
  return {
    id: uuidv4(), language, targetWord, nativeWord, tags,
    example, exampleTranslation, notes,
    createdAt: new Date().toISOString(),
    reviewCount: 0, correctCount: 0, streak: 0, mastery: 0, interval: 0,
  };
}

const hu = (t: string, n: string, tags: Tag[], ex?: string, exT?: string, notes?: string) =>
  card('hungarian', t, n, tags, ex, exT, notes);

const fr = (t: string, n: string, tags: Tag[], ex?: string, exT?: string, notes?: string) =>
  card('french', t, n, tags, ex, exT, notes);

const it = (t: string, n: string, tags: Tag[], ex?: string, exT?: string, notes?: string) =>
  card('italian', t, n, tags, ex, exT, notes);

